code:
let lockers = [[true, true, false],
               [false, true, true]]   // true — занята
var found: (row: Int, column: Int)? = nil
for row in lockers.indices {
    for column in lockers[row].indices {
        if !lockers[row][column] {
            found = (row, column)
            break
        }
    }
}
print(found as Any)

key:
search: for row in lockers.indices {
    for column in lockers[row].indices {
        if !lockers[row][column] {
            found = (row, column)
            break search
        }
    }
}
print(found as Any)

break без метки выходит только из внутреннего цикла: внешний переходит к ряду 1 и перезаписывает found ячейкой (1, 0). Метка search: у внешнего цикла и break search завершают оба цикла сразу. Другой вариант — вынести поиск в функцию и вернуть (row, column) через return прямо из вложенного цикла. Вывод: Optional((row: 0, column: 2)).

